const normalize=s=>s.replace(/\s+/g,' ').trim();
const sourceText=new WeakMap(), sourceAttributes=new WeakMap();
let language='en';
function translate(value){const en=normalize(value);return language==='cn'&&pairs[en]?value.replace(value.trim(),pairs[en]):value;}
function localize(root){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){
  if(node.parentElement?.closest('script,style,[data-language-switch]'))continue;
  let record=sourceText.get(node);if(!record||node.data!==record.rendered)record={source:node.data};
  const value=translate(record.source);record.rendered=value;sourceText.set(node,record);if(value!==node.data)node.data=value;
 }
 const elements=root.nodeType===1?[root,...root.querySelectorAll('*')]:[...root.querySelectorAll('*')];
 for(const el of elements){if(el.closest('[data-language-switch]'))continue;let records=sourceAttributes.get(el);if(!records){records=new Map();sourceAttributes.set(el,records);}for(const attr of ['aria-label','aria-valuetext','title','alt'])if(el.hasAttribute(attr)){const old=el.getAttribute(attr);let record=records.get(attr);if(!record||old!==record.rendered)record={source:old};const value=translate(record.source);record.rendered=value;records.set(attr,record);if(old!==value)el.setAttribute(attr,value);}}
}
export function preferredLanguage(locale){return /^zh(?:-|$)/i.test(locale||'')?'cn':'en';}
export function initLanguage(){
 function selectLanguage(next){language=next;document.documentElement.lang=next==='cn'?'zh-CN':'en';document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===next)));localize(document.body);document.title=next==='cn'?'EARTH / FORM · 陶土成器':'Earth / Form — A study in becoming';document.dispatchEvent(new Event('languagechange'));}

 for(const target of [document.querySelector('.header nav'),document.querySelector('.studio-header')]){
 const group=document.createElement('div');group.className='language-switch';group.dataset.languageSwitch='';group.setAttribute('role','group');group.setAttribute('aria-label','Language / 语言');group.innerHTML='<button type="button" data-lang="en" aria-pressed="true" lang="en">EN</button><span>/</span><button type="button" data-lang="cn" aria-pressed="false" lang="zh-CN">中文</button>';target.append(group);
 group.addEventListener('click',e=>{const next=e.target.dataset.lang;if(!next)return;selectLanguage(next);});
 }
 selectLanguage(preferredLanguage(navigator.languages?.[0]||navigator.language));
 const observer=new MutationObserver(records=>{const roots=new Set();for(const r of records){if(r.type==='characterData')roots.add(r.target.parentElement);else if(r.type==='attributes')roots.add(r.target);else roots.add(r.target);}observer.disconnect();for(const root of roots)if(root?.isConnected)localize(root);observe();});
 function observe(){observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','aria-valuetext','title','alt']});}observe();
}
